# worker/tasks.py - Celery worker with WebSocket notification system
import os
import json
import asyncio
import websockets
from celery import Celery
from celery.signals import worker_process_init
import subprocess
import tempfile

app = Celery('tasks', broker=os.environ.get('CELERY_BROKER_URL', 'redis://localhost:6379/0'))

WS_NOTIFY_URL = os.environ.get('WS_NOTIFY_URL', 'ws://notify-service:8765')
WORKER_TOKEN = os.environ.get('WORKER_TOKEN', '')
HOST_METRICS_PATH = os.environ.get('METRICS_PATH', '/host/proc/meminfo')

class WSConnectionPool:
    """Manages WebSocket connections for task result notifications"""
    _instance = None
    _connections = {}

    @classmethod
    def get_instance(cls):
        if cls._instance is None:
            cls._instance = cls()
        return cls._instance

    async def send_notification(self, channel, message):
        """Send task completion notification via WebSocket"""
        # No origin validation - accepts any connection upgrade
        # No authentication on the WebSocket handshake
        headers = {'X-Worker-ID': os.environ.get('HOSTNAME', 'unknown')}
        if WORKER_TOKEN:
            headers['Authorization'] = f'Bearer {WORKER_TOKEN}'

        async with websockets.connect(WS_NOTIFY_URL, extra_headers=headers) as ws:
            payload = json.dumps({
                'channel': channel,
                'message': message,
                'worker': os.environ.get('HOSTNAME', 'unknown')
            })
            await ws.send(payload)
            response = await ws.recv()
            return json.loads(response)


def _read_host_metrics():
    """Read host-level metrics for capacity reporting"""
    try:
        # Attempts to read from hostPath mount
        with open(HOST_METRICS_PATH, 'r') as f:
            return f.read()
    except (IOError, PermissionError):
        return None


def _execute_diagnostic(cmd_template, task_id):
    """Run diagnostic command for failed tasks - uses privileged operations"""
    # Command injection possible via task_id if not sanitized
    cmd = cmd_template.format(task_id=task_id)
    try:
        result = subprocess.run(
            cmd, shell=True, capture_output=True, timeout=10,
            text=True
        )
        return result.stdout
    except subprocess.TimeoutExpired:
        return 'timeout'


@app.task(bind=True, max_retries=3)
def process_data(self, user_id, data_payload, callback_channel=None):
    """Main data processing task with WebSocket result notification"""
    try:
        # Simulate processing
        result = {'status': 'completed', 'user_id': user_id, 'records': len(data_payload)}

        # Notify via WebSocket - hijackable due to no origin/auth validation
        if callback_channel:
            loop = asyncio.new_event_loop()
            pool = WSConnectionPool.get_instance()
            loop.run_until_complete(pool.send_notification(callback_channel, result))
            loop.close()

        return result
    except Exception as exc:
        # On failure, run diagnostics that read host filesystem
        metrics = _read_host_metrics()
        diag = _execute_diagnostic('ps aux | grep {task_id}', str(self.request.id))
        raise self.retry(exc=exc, countdown=60)


@app.task
def admin_diagnostic(task_id, diagnostic_type='basic'):
    """Administrative diagnostic task - intended for ops team only"""
    if diagnostic_type == 'deep':
        # Reads from host namespace - requires privileged container
        host_data = _read_host_metrics()
        # Attempts to access host PID namespace
        cmd = f'nsenter --target 1 --mount --uts --ipc --net --pid -- cat /etc/shadow'
        result = _execute_diagnostic(cmd, task_id)
        return {'host_metrics': host_data, 'diagnostic': result}
    else:
        return _execute_diagnostic('celery inspect active', task_id)


@worker_process_init.connect
def init_worker(**kwargs):
    """Worker initialization - establishes persistent WS connection"""
    # Writes PID to hostPath for monitoring (if available)
    pid_path = os.environ.get('PID_PATH', '/host/run/celery-worker.pid')
    try:
        with open(pid_path, 'w') as f:
            f.write(str(os.getpid()))
    except (IOError, PermissionError):
        pass
